// Real elevation: USGS 3DEP (public domain) via The National Map ImageServer.
// 180x216 samples over lon -71.48218..-71.44953, lat 42.25305 (row 0, north) .. 42.22392.
// q = round((elev_m - 50) / 0.5); stored as Int8 deltas (pred = left neighbour; col 0 uses pixel above).
export const DEM = { w:180, h:216, lon0:-71.48218, lon1:-71.44953, lat0:42.25305, lat1:42.22392, off:50, step:0.5, RES_ELEV:66.2,
  b64:"" };
let _q=null;
function build(){
  const bin=atob(DEM.b64), n=DEM.w*DEM.h, q=new Int16Array(n);
  for(let r=0;r<DEM.h;r++)for(let c=0;c<DEM.w;c++){
    const i=r*DEM.w+c; let d=bin.charCodeAt(i); if(d>127)d-=256;
    q[i]=d+(c>0?q[i-1]:(r>0?q[i-DEM.w]:0));
  }
  const e=new Float32Array(n); for(let i=0;i<n;i++)e[i]=DEM.off+q[i]*DEM.step; return e;
}
// Bilinear real elevation (m above sea level) at lat/lon.
export function elevLatLon(lat,lon){
  if(!_q)_q=build();
  const fx=(lon-DEM.lon0)/(DEM.lon1-DEM.lon0)*(DEM.w-1), fy=(DEM.lat0-lat)/(DEM.lat0-DEM.lat1)*(DEM.h-1);
  const x=Math.min(DEM.w-1.001,Math.max(0,fx)), y=Math.min(DEM.h-1.001,Math.max(0,fy));
  const x0=x|0,y0=y|0,tx=x-x0,ty=y-y0,W=DEM.w;
  const a=_q[y0*W+x0],b=_q[y0*W+x0+1],c=_q[(y0+1)*W+x0],d=_q[(y0+1)*W+x0+1];
  return (a*(1-tx)+b*tx)*(1-ty)+(c*(1-tx)+d*tx)*ty;
}
